import React, { useState, useRef, useCallback } from 'react';
import CMSLayout from '../../components/cms/CMSLayout';
import { AuthProvider } from '../../context/AuthContext';
import {
  FaCloudUploadAlt, FaSearchPlus, FaTrash, FaTimes,
  FaChevronLeft, FaChevronRight, FaImages,
} from 'react-icons/fa';
import { GALLERY } from '../../content';

interface GalleryImage {
  id: number;
  src: string;
  title: string;
}

const ImagesContent: React.FC = () => {
  // Initialize with the gallery images from content.tsx
  const [images, setImages] = useState<GalleryImage[]>(
    GALLERY.images.map((img) => ({
      id: img.id,
      src: img.src,
      title: img.title,
    }))
  );

  const [showUpload, setShowUpload] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [uploading, setUploading] = useState<{ name: string; progress: number; preview: string }[]>([]);
  const [deleteModal, setDeleteModal] = useState<GalleryImage | null>(null);
  const [deleting, setDeleting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Open lightbox
  const openLightbox = (index: number) => {
    setLightboxIndex(index);
    setLightboxOpen(true);
  };

  const closeLightbox = () => setLightboxOpen(false);

  const prevImage = () => {
    setLightboxIndex((prev) => (prev === 0 ? images.length - 1 : prev - 1));
  };

  const nextImage = () => {
    setLightboxIndex((prev) => (prev === images.length - 1 ? 0 : prev + 1));
  };

  // Keyboard nav
  React.useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (!lightboxOpen) return;
      if (e.key === 'Escape') closeLightbox();
      if (e.key === 'ArrowLeft') prevImage();
      if (e.key === 'ArrowRight') nextImage();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [lightboxOpen, images.length]);

  // Delete image (frontend-only, removes from state)
  const confirmDelete = (image: GalleryImage) => {
    setDeleteModal(image);
  };

  const handleDelete = () => {
    if (!deleteModal) return;
    setDeleting(true);
    // Simulate brief delay for UX feel
    setTimeout(() => {
      setImages((prev) => prev.filter((img) => img.id !== deleteModal.id));
      setDeleteModal(null);
      setDeleting(false);
    }, 400);
  };

  // Handle file selection (simulated upload — no backend yet)
  const handleFiles = useCallback((files: FileList | null) => {
    if (!files || files.length === 0) return;

    const newUploads: { name: string; progress: number; preview: string }[] = [];

    Array.from(files).forEach((file) => {
      if (!file.type.startsWith('image/')) return;

      const preview = URL.createObjectURL(file);
      newUploads.push({ name: file.name, progress: 0, preview });

      // Simulate upload progress
      const uploadIndex = uploading.length + newUploads.length - 1;
      let progress = 0;

      const interval = setInterval(() => {
        progress += Math.random() * 30 + 10;
        if (progress >= 100) {
          progress = 100;
          clearInterval(interval);

          // Add to images when "done"
          setTimeout(() => {
            const newImage: GalleryImage = {
              id: Date.now() + Math.random(),
              src: preview,
              title: file.name.replace(/\.[^/.]+$/, ''),
            };
            setImages((prev) => [newImage, ...prev]);
            setUploading((prev) => prev.filter((u) => u.name !== file.name));
          }, 500);
        }

        setUploading((prev) =>
          prev.map((u) => (u.name === file.name ? { ...u, progress: Math.min(progress, 100) } : u))
        );
      }, 300);
    });

    setUploading((prev) => [...prev, ...newUploads]);
  }, [uploading.length]);

  // Drag and drop
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = () => setDragOver(false);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    handleFiles(e.dataTransfer.files);
  };

  return (
    <CMSLayout activePage="images">
      <div className="cms-page-header">
        <h1>Gallery Images</h1>
        <p>Manage images that appear in your website gallery section.</p>
      </div>

      {/* Toolbar */}
      <div className="cms-images-toolbar">
        <span className="image-count">{images.length} images</span>
        <button className="cms-upload-btn" onClick={() => setShowUpload(!showUpload)}>
          <FaCloudUploadAlt /> {showUpload ? 'Hide Upload' : 'Upload Images'}
        </button>
      </div>

      {/* Upload area */}
      {showUpload && (
        <div
          className={`cms-upload-area ${dragOver ? 'drag-over' : ''}`}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
        >
          <FaCloudUploadAlt />
          <h3>Drop images here or <span className="browse-link">browse</span></h3>
          <p>Supports JPG, PNG, WebP. Max 10MB per file.</p>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            multiple
            style={{ display: 'none' }}
            onChange={(e) => handleFiles(e.target.files)}
          />
        </div>
      )}

      {/* Upload progress */}
      {uploading.map((upload) => (
        <div className="cms-upload-progress" key={upload.name}>
          <img src={upload.preview} alt="" className="upload-thumb" />
          <div className="upload-info">
            <div className="upload-name">{upload.name}</div>
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${upload.progress}%` }} />
            </div>
            <div className="upload-status">
              {upload.progress < 100 ? `Uploading... ${Math.round(upload.progress)}%` : 'Processing...'}
            </div>
          </div>
        </div>
      ))}

      {/* Image grid */}
      {images.length > 0 ? (
        <div className="cms-image-grid">
          {images.map((image, index) => (
            <div className="cms-image-card" key={image.id}>
              <img src={image.src} alt={image.title} loading="lazy" />
              <div className="image-info">
                <div className="image-title">{image.title}</div>
                <div className="image-meta">Gallery Image</div>
              </div>
              <div className="image-overlay">
                <button
                  className="cms-image-action"
                  onClick={() => openLightbox(index)}
                  title="View full size"
                >
                  <FaSearchPlus />
                </button>
                <button
                  className="cms-image-action delete"
                  onClick={() => confirmDelete(image)}
                  title="Remove image"
                >
                  <FaTrash />
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="cms-empty-state">
          <FaImages />
          <h3>No images yet</h3>
          <p>Upload images to populate your website gallery.</p>
        </div>
      )}

      {/* Lightbox */}
      {lightboxOpen && images[lightboxIndex] && (
        <div className="cms-lightbox" onClick={closeLightbox}>
          <button className="cms-lightbox-close" onClick={closeLightbox}>
            <FaTimes />
          </button>
          <button
            className="cms-lightbox-nav prev"
            onClick={(e) => { e.stopPropagation(); prevImage(); }}
          >
            <FaChevronLeft />
          </button>
          <img
            src={images[lightboxIndex].src}
            alt={images[lightboxIndex].title}
            onClick={(e) => e.stopPropagation()}
          />
          <button
            className="cms-lightbox-nav next"
            onClick={(e) => { e.stopPropagation(); nextImage(); }}
          >
            <FaChevronRight />
          </button>
          <div className="cms-lightbox-title">
            {images[lightboxIndex].title} ({lightboxIndex + 1}/{images.length})
          </div>
        </div>
      )}
      {/* Delete Confirmation Modal */}
      {deleteModal && (
        <div className="cms-delete-overlay" onClick={() => !deleting && setDeleteModal(null)}>
          <div className="cms-delete-modal" onClick={(e) => e.stopPropagation()}>
            <div className="cms-delete-modal-icon">
              <FaTrash />
            </div>
            <div className="cms-delete-modal-preview">
              <img src={deleteModal.src} alt={deleteModal.title} />
            </div>
            <h3>Delete Image?</h3>
            <p>Are you sure you want to remove <strong>{deleteModal.title}</strong> from the gallery? This action cannot be undone.</p>
            <div className="cms-delete-modal-actions">
              <button
                className="cms-modal-btn cancel"
                onClick={() => setDeleteModal(null)}
                disabled={deleting}
              >
                Cancel
              </button>
              <button
                className="cms-modal-btn confirm"
                onClick={handleDelete}
                disabled={deleting}
              >
                {deleting ? 'Deleting...' : 'Yes, Delete'}
              </button>
            </div>
          </div>
        </div>
      )}
    </CMSLayout>
  );
};

const ImagesPage: React.FC = () => {
  return (
    <AuthProvider>
      <ImagesContent />
    </AuthProvider>
  );
};

export default ImagesPage;
